     "type": "md",
     "text": "РК: А22 (общее уравнение и уравнение в отрезках), А23 (через три точки), А24 (взаимное расположение), А25 (расстояние от точки), Б8 (вывод формулы расстояния). Задачи 416–424, 431–448, 454–459.\n\n## Суть\nПлоскость задаётся точкой $M_0$ и нормалью $\\vec n\\perp$ плоскости: точка $M$ лежит в плоскости $\\iff\\vec n\\cdot\\overrightarrow{M_0M}=0$. Раскрыв скалярное произведение, получаем линейное уравнение $Ax+By+Cz+D=0$, где $\\{A,B,C\\}=\\vec n$. Почти любая задача сводится к поиску одной точки и нормали."
