     "type": "md",
     "text": "**Через три точки (А23)** $M_1,M_2,M_3$, не лежащие на одной прямой: векторы $\\overrightarrow{M_1M},\\overrightarrow{M_1M_2},\\overrightarrow{M_1M_3}$ компланарны:\n$$\\begin{vmatrix}x-x_1&y-y_1&z-z_1\\\\x_2-x_1&y_2-y_1&z_2-z_1\\\\x_3-x_1&y_3-y_1&z_3-z_1\\end{vmatrix}=0.$$\n\n**Через точку и два неколлинеарных направления** $\\vec u,\\vec v$ (параметрически): $M=M_0+\\lambda\\vec u+\\mu\\vec v$, нормаль $\\vec n=\\vec u\\times\\vec v$.\n\n## Взаимное расположение двух плоскостей (А24)\nПусть $\\vec n_1=\\{A_1,B_1,C_1\\}$, $\\vec n_2=\\{A_2,B_2,C_2\\}$."
