     "text": "Возьмём на плоскости $\\pi$ любую точку $M_1(x_1,y_1,z_1)$: $Ax_1+By_1+Cz_1+D=0$, то есть $D=-(Ax_1+By_1+Cz_1)$.\nИскомое расстояние — модуль проекции $\\overrightarrow{M_1M_0}$ на нормаль:\n$$\\rho=\\left|\\operatorname{Пр}_{\\vec n}\\overrightarrow{M_1M_0}\\right|=\\frac{|\\overrightarrow{M_1M_0}\\cdot\\vec n|}{|\\vec n|}.$$\nСчитаем числитель:\n$$\\overrightarrow{M_1M_0}\\cdot\\vec n=A(x_0-x_1)+B(y_0-y_1)+C(z_0-z_1)=Ax_0+By_0+Cz_0-(Ax_1+By_1+Cz_1)=Ax_0+By_0+Cz_0+D.$$\nЗнаменатель $|\\vec n|=\\sqrt{A^2+B^2+C^2}$. $\\blacksquare$"
