     "type": "md",
     "text": "**Знак** $f(M)=Ax+By+Cz+D$ показывает, с какой стороны плоскости лежит точка: точки с одинаковым знаком — по одну сторону [не из конспекта; нужно в задачах 434, 443–449].\n\n**Расстояние между параллельными плоскостями** $Ax+By+Cz+D_1=0$ и $Ax+By+Cz+D_2=0$ (коэффициенты при $x,y,z$ **одинаковые**):\n$$\\rho=\\frac{|D_1-D_2|}{\\sqrt{A^2+B^2+C^2}}.$$\n\n## Пучок плоскостей и биссекторные плоскости [не из конспекта; задачи 424, 441–447, 456]\n**Пучок** — все плоскости, проходящие через прямую $\\{\\Pi_1=0,\\ \\Pi_2=0\\}$:\n$$\\alpha(A_1x+B_1y+C_1z+D_1)+\\beta(A_2x+B_2y+C_2z+D_2)=0,\\qquad \\alpha^2+\\beta^2\\ne0.$$\nУдобно, когда нужна плоскость «через линию пересечения … и ещё одно условие»: одно условие определяет отношение $\\alpha:\\beta$.\n\n**Биссекторные плоскости** двугранных углов — точки, равноудалённые от двух плоскостей:\n$$\\frac{A_1x+B_1y+C_1z+D_1}{\\sqrt{A_1^2+B_1^2+C_1^2}}=\\pm\\frac{A_2x+B_2y+C_2z+D_2}{\\sqrt{A_2^2+B_2^2+C_2^2}}.$$"
