     "type": "details",
     "kind": "proof",
     "title": "Почему так [не из конспекта]",
     "src": "extra",
     "text": "Область $\\{f_1>0,\\ f_2>0\\}$ — двугранный угол, из которого нормали $\\vec n_1,\\vec n_2$ «смотрят внутрь». Его величина равна $\\pi-\\angle(\\vec n_1,\\vec n_2)$. Она острая $\\iff\\angle(\\vec n_1,\\vec n_2)>\\frac\\pi2\\iff\\vec n_1\\cdot\\vec n_2<0$. Смена знака $f_2$ — это замена $\\vec n_2$ на $-\\vec n_2$, поэтому для области $\\{f_1>0,\\ f_2<0\\}$ условие обратное. Вместе: острый угол $\\iff f_1f_2(\\vec n_1\\cdot\\vec n_2)<0$. Внутри угла знаки $f_1,f_2$ постоянны, поэтому его биссектор — та из двух плоскостей, на которой $\\frac{f_1}{|\\vec n_1|}$ и $\\frac{f_2}{|\\vec n_2|}$ имеют знаки этого угла."
