     "text": "Построим параллелограмм на векторах $\\vec s$ и $\\overrightarrow{M_0M_1}$, отложенных от $M_0$. Его площадь:\n1. через векторное произведение: $S=|\\overrightarrow{M_0M_1}\\times\\vec s|$;\n2. через основание и высоту: $S=|\\vec s|\\cdot h$, где $h$ — высота, опущенная из $M_1$ на прямую $L$, то есть $h=\\rho(M_1,L)$.\n\nПриравниваем: $|\\vec s|\\cdot\\rho=|\\overrightarrow{M_0M_1}\\times\\vec s|$. $\\blacksquare$"
