     "text": "**Линейный базис** $\\{\\vec e_1,\\vec e_2,\\dots\\}$: всякий $\\vec v\\in V$ единственным образом представим как $\\vec v=\\alpha_1\\vec e_1+\\dots+\\alpha_m\\vec e_m$ (базис Гамеля)."
