     "type": "md",
     "text": "Линейность по второму аргументу следует из первой и симметричности. Векторы **ортогональны**, если $\\langle\\vec u,\\vec v\\rangle=0$. Базис **ортонормированный**, если $\\langle\\vec e_i,\\vec e_j\\rangle=0$ при $i\\ne j$ и $1$ при $i=j$.\n\n**Норма** $\\|\\cdot\\|$ — функция на $V$, для которой:\n1. $\\|\\alpha\\vec v\\|=|\\alpha|\\cdot\\|\\vec v\\|$ (однородность);\n2. $\\vec v\\ne\\vec 0\\Rightarrow\\|\\vec v\\|>0$;\n3. $\\|\\vec x+\\vec y\\|\\le\\|\\vec x\\|+\\|\\vec y\\|$ (неравенство треугольника).\n\nСкалярное произведение порождает евклидову норму $\\|\\vec v\\|=\\sqrt{\\langle\\vec v,\\vec v\\rangle}$; неравенство треугольника для неё следует из неравенства Коши–Буняковского $|\\langle\\vec u,\\vec v\\rangle|\\le\\|\\vec u\\|\\,\\|\\vec v\\|$ [не из конспекта]."
