     "text": "## 2. Типовые построения\n\n**Основание перпендикуляра из точки $P$ на плоскость** $Ax+By+Cz+D=0$:\n$$H=P-\\frac{f(P)}{|\\vec n|^2}\\,\\vec n,\\qquad f(P)=Ax_P+By_P+Cz_P+D.$$\n\n**Основание перпендикуляра из $P$ на прямую** $M_0+t\\vec s$:\n$$t^*=\\frac{\\overrightarrow{M_0P}\\cdot\\vec s}{|\\vec s|^2},\\qquad H=M_0+t^*\\vec s.$$\n\n**Симметричная точка** относительно плоскости или прямой: $P'=2H-P$ (основание $H$ — середина $PP'$)."
