     "text": "## 4. Пучок, биссекторы, острый/тупой угол\n\n- «Плоскость через линию пересечения $\\Pi_1,\\Pi_2$ и …» — пучок $\\alpha\\Pi_1+\\beta\\Pi_2=0$, оставшееся условие даёт $\\alpha:\\beta$. Не забудь проверить сами $\\Pi_1$ и $\\Pi_2$ (случай $\\beta=0$ или $\\alpha=0$).\n- Биссекторы: $\\dfrac{f_1}{|\\vec n_1|}=\\pm\\dfrac{f_2}{|\\vec n_2|}$.\n- Точка $M$ в **остром** угле $\\iff f_1(M)f_2(M)(\\vec n_1\\cdot\\vec n_2)<0$.\n- Биссектор угла, содержащего точку $M$: знак в $\\pm$ выбрать так, чтобы $\\frac{f_1(M)}{|\\vec n_1|}$ и $\\pm\\frac{f_2(M)}{|\\vec n_2|}$ были одного знака.\n\n## 5. Проверка ответа (30 секунд, но спасает баллы)\n1. Подставь заданные точки в найденное уравнение — должны обнулять.\n2. Проверь перпендикулярность/параллельность через скалярное или векторное произведение.\n3. Расстояние не может быть отрицательным, косинус угла между плоскостями — больше 1."
