   {
    "id": "C1",
    "label": "В1",
    "block": "C",
    "n": 1,
    "points": null,
    "q": "Аксиомы векторного (линейного) пространства V(ℝ)",
    "answer": "Множество $V$ с операциями сложения и умножения на число из $\\mathbb R$, $\\forall\\vec u,\\vec v,\\vec w\\in V$, $\\forall\\alpha,\\beta\\in\\mathbb R$:\n1. $(\\vec u+\\vec v)+\\vec w=\\vec u+(\\vec v+\\vec w)$;\n2. $\\exists\\vec 0\\in V:\\ \\vec v+\\vec 0=\\vec v$;\n3. $\\exists(-\\vec v)\\in V:\\ \\vec v+(-\\vec v)=\\vec 0$;\n4. $\\vec u+\\vec v=\\vec v+\\vec u$;\n5. $(\\alpha\\beta)\\vec v=\\alpha(\\beta\\vec v)$;\n6. $1\\cdot\\vec v=\\vec v$;\n7. $\\alpha(\\vec u+\\vec v)=\\alpha\\vec u+\\alpha\\vec v$;\n8. $(\\alpha+\\beta)\\vec v=\\alpha\\vec v+\\beta\\vec v$.",
    "refs": [
     "g09"
    ]
   },
   {
    "id": "C2",
    "label": "В2",
    "block": "C",
    "n": 2,
    "points": null,
    "q": "Аксиомы скалярного произведения и нормы",
    "answer": "**Скалярное произведение** $\\langle\\vec u,\\vec v\\rangle$ в $V(\\mathbb R)$:\n- линейность: $\\langle\\alpha\\vec u,\\vec v\\rangle=\\alpha\\langle\\vec u,\\vec v\\rangle$, $\\langle\\vec u+\\vec w,\\vec v\\rangle=\\langle\\vec u,\\vec v\\rangle+\\langle\\vec w,\\vec v\\rangle$;\n- симметричность: $\\langle\\vec u,\\vec v\\rangle=\\langle\\vec v,\\vec u\\rangle$;\n- положительная определённость и невырожденность: $\\langle\\vec v,\\vec v\\rangle\\ge0$, $\\langle\\vec v,\\vec v\\rangle=0\\iff\\vec v=\\vec 0$.\n\n**Норма:** $\\|\\alpha\\vec v\\|=|\\alpha|\\,\\|\\vec v\\|$; $\\vec v\\ne\\vec 0\\Rightarrow\\|\\vec v\\|>0$; $\\|\\vec x+\\vec y\\|\\le\\|\\vec x\\|+\\|\\vec y\\|$. Скалярное произведение порождает норму $\\|\\vec v\\|=\\sqrt{\\langle\\vec v,\\vec v\\rangle}$.",
    "refs": [
     "g09"
    ]
   },
   {
    "id": "C3",
    "label": "В3",
    "block": "C",
    "n": 3,
    "points": null,
    "q": "Двойное векторное произведение и тождества",
    "answer": "$$[\\vec u,[\\vec v,\\vec w]]=\\vec v\\langle\\vec u,\\vec w\\rangle-\\vec w\\langle\\vec u,\\vec v\\rangle\\qquad\\text{(тождество Лагранжа у лектора, «бац минус цаб»)};$$\n$$[\\vec u,[\\vec v,\\vec w]]+[\\vec v,[\\vec w,\\vec u]]+[\\vec w,[\\vec u,\\vec v]]=\\vec 0\\qquad\\text{(тождество Якоби)}.$$",
    "refs": [
     "g06",
     "g09"
    ]
   },
   {
    "id": "C4",
    "label": "В4",
    "block": "C",
    "n": 4,
    "points": null,
    "q": "Аффинное пространство и аффинное подпространство",
    "answer": "**Аффинное пространство** $A(V)$ — множество точек с операцией сдвига точки на вектор $P+\\vec v=Q$:\n1. $(P+\\vec u)+\\vec v=P+(\\vec u+\\vec v)$;\n2. $\\forall P,Q\\in A\\ \\exists!\\,\\vec v\\in V:\\ P+\\vec v=Q$ (обозначение $\\overrightarrow{PQ}$).\n\n**Аффинное подпространство** через точку $P_0$ с направляющим линейным подпространством $V_0\\subseteq V$:\n$$L=P_0+V_0=\\{P\\in A\\mid P=P_0+\\vec v,\\ \\vec v\\in V_0\\},\\qquad\\dim L=\\dim V_0.$$",
    "refs": [
     "g09"
    ]
   },
   {
    "id": "C5",
    "label": "В5",
    "block": "C",
    "n": 5,
    "points": null,
    "q": "Геометрические примеры аффинных подпространств",
    "answer": "- $\\dim0$: $V_0=\\{\\vec 0\\}$, $P=P_0$ — точка;\n- $\\dim1$: $V_0=\\operatorname{span}\\{\\vec s\\}$, $P=P_0+t\\vec s$ — прямая;\n- $\\dim2$: $V_0=\\operatorname{span}\\{\\vec u,\\vec v\\}$, $P=P_0+\\lambda\\vec u+\\mu\\vec v$ — плоскость;\n- $\\dim3$: $V_0=V_3$, $P=P_0+\\vec v$ — всё пространство.",
    "refs": [
     "g09"
    ],
    "figure": "affine"
   }
