    "q": "Найти уравнение перпендикуляра, опущенного из точки $P(1,-1,2)$ на прямую $\\ell:\\ \\dfrac x2=\\dfrac{y-2}1=\\dfrac{z+1}{-1}$, и расстояние от точки $P$ до прямой $\\ell$.",
    "hint": "Основание $H=M_0+t^*\\vec s$, $t^*$ из $\\overrightarrow{PH}\\cdot\\vec s=0$.",
    "solution": "$M_0(0,2,-1)$, $\\vec s=\\{2,1,-1\\}$, $H=(2t,\\ 2+t,\\ -1-t)$.\n$\\overrightarrow{PH}=\\{2t-1,\\ t+3,\\ -t-3\\}$; $\\overrightarrow{PH}\\cdot\\vec s=6t+4=0\\Rightarrow t=-\\frac23$.\n$H=\\left(-\\frac43,\\frac43,-\\frac13\\right)$, $\\overrightarrow{PH}=-\\frac73\\{1,-1,1\\}$.\n$\\rho=|\\overrightarrow{PH}|=\\frac73\\sqrt3=\\frac7{\\sqrt3}$ (сходится с формулой $\\frac{|\\overrightarrow{M_0P}\\times\\vec s|}{|\\vec s|}=\\frac{7\\sqrt2}{\\sqrt6}$).\n**Ответ:** $\\dfrac{x-1}1=\\dfrac{y+1}{-1}=\\dfrac{z-2}1$; $\\ \\rho=\\dfrac7{\\sqrt3}=\\dfrac{7\\sqrt3}3$.",
