    "hint": "Перпендикуляр — пересечение двух плоскостей: через $M_1$ перпендикулярно прямой и через прямую и $M_1$.",
    "solution": "Обе плоскости содержат $M_1$ и основание $H$, поэтому их пересечение — прямая $M_1H$.\n**Ответ:**\n$$\\begin{cases}a(x-x_1)+b(y-y_1)+c(z-z_1)=0,\\\\[2pt]\\begin{vmatrix}x-x_0&y-y_0&z-z_0\\\\a&b&c\\\\x_1-x_0&y_1-y_0&z_1-z_0\\end{vmatrix}=0\\end{cases}$$\n($M_1$ не на прямой). Основание: $H=M_0+t^*\\vec s$, $t^*=\\dfrac{a(x_1-x_0)+b(y_1-y_0)+c(z_1-z_0)}{a^2+b^2+c^2}$.",
