    "type": "bisect",
    "q": "Даны плоскости $\\Pi_1:\\ 4x+y-8z-1=0$ и $\\Pi_2:\\ x-2y+2z+3=0$. Найти уравнение такой плоскости $\\Pi_3$, что $\\Pi_2$ делит пополам двугранный угол между $\\Pi_1$ и $\\Pi_3$.",
