    "solution": "Отражение нормали: $\\vec n_1'=\\vec n_1-2\\frac{\\vec n_1\\cdot\\vec n_2}{|\\vec n_2|^2}\\vec n_2=\\{4,1,-8\\}+\\frac{28}9\\{1,-2,2\\}=\\frac19\\{64,-47,-16\\}$.\nВ пучке $\\Pi_1+\\lambda\\Pi_2$: $\\{4+\\lambda,\\ 1-2\\lambda,\\ -8+2\\lambda\\}\\parallel\\{64,-47,-16\\}\\Rightarrow\\lambda=\\frac{28}9$.\n$9\\Pi_1+28\\Pi_2=0$.\n**Ответ:** $64x-47y-16z+75=0$.",
