    "q": "Найти необходимые и достаточные условия для того, чтобы точка $(x_0,y_0,z_0)$ лежала в остром угле, образуемом двумя пересекающимися и не взаимно перпендикулярными плоскостями $A_1x+B_1y+C_1z+D_1=0$, $A_2x+B_2y+C_2z+D_2=0$.",
    "hint": "Знаки $f_1,f_2$ задают один из четырёх углов; величина угла $\\{f_1>0,f_2>0\\}$ равна $\\pi-\\angle(\\vec n_1,\\vec n_2)$.",
    "solution": "Угол $\\{f_1>0,f_2>0\\}$ острый $\\iff\\angle(\\vec n_1,\\vec n_2)>\\frac\\pi2\\iff\\vec n_1\\cdot\\vec n_2<0$. Смена знака $f_2$ равносильна замене $\\vec n_2\\to-\\vec n_2$. Объединяя все случаи:\n**Ответ:** $(A_1x_0+B_1y_0+C_1z_0+D_1)(A_2x_0+B_2y_0+C_2z_0+D_2)(A_1A_2+B_1B_2+C_1C_2)<0$.",
