    "hint": "Сечение призмы — треугольник; внутренние нормали $\\vec\\nu_k$, угол при ребре $(i,j)$ острый $\\iff\\vec\\nu_i\\cdot\\vec\\nu_j<0$.",
    "solution": "Нормали лежат в одной плоскости (⊥ рёбрам), и $\\lambda_1\\vec n_1+\\lambda_2\\vec n_2+\\lambda_3\\vec n_3=\\vec 0$ с внутренними нормалями $\\vec\\nu_k=\\pm\\operatorname{sign}(\\lambda_k)\\vec n_k$ (сумма внутренних нормалей с весами-длинами сторон равна нулю). Тогда знак $\\vec\\nu_i\\cdot\\vec\\nu_j$ совпадает со знаком $\\lambda_i\\lambda_j(\\vec n_i\\cdot\\vec n_j)$. В треугольнике не больше одного неострого угла, поэтому из трёх величин хотя бы две отрицательны, и все три отрицательны $\\iff$ их произведение $(\\lambda_1\\lambda_2\\lambda_3)^2\\prod(\\vec n_i\\cdot\\vec n_j)<0$.\n**Ответ:** $(A_1A_2+B_1B_2+C_1C_2)(A_2A_3+B_2B_3+C_2C_3)(A_3A_1+B_3B_1+C_3C_1)<0$.",
