   "group": "tasks",
   "text": "Ловушка: подставить в $\\frac{|D_1-D_2|}{|\\vec n|}$ числа $-1$ и $1$ из уравнений $2x-4y-2z-1=0$ и $3x-6y-3z+1=0$ как есть.\nПравильно: сначала привести к одинаковым коэффициентам при $x,y,z$ (поделить на $2$ и $3$), тогда $D_1=-\\frac12$, $D_2=\\frac13$, ответ $\\frac{5\\sqrt6}{36}$."
