  "cross": "<svg viewBox=\"0 0 320 220\" xmlns=\"http://www.w3.org/2000/svg\" class=\"fig\" font-size=\"12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\"><defs><marker id=\"agA\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"currentColor\" stroke=\"none\"/></marker><marker id=\"agB\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" style=\"fill:var(--accent)\" stroke=\"none\"/></marker></defs><polygon points=\"100,170 82.1,203.9 197.8,208.2 215.8,174.2\" fill=\"currentColor\" fill-opacity=\".10\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\".5\"/><line x1=\"100\" y1=\"170\" x2=\"82.1\" y2=\"203.9\" marker-end=\"url(#agA)\"/><text x=\"76.1\" y=\"192.7\" stroke=\"none\" fill=\"currentColor\" font-style=\"italic\" font-weight=\"600\">a</text><line x1=\"100\" y1=\"170\" x2=\"215.8\" y2=\"174.2\" marker-end=\"url(#agA)\"/><text x=\"190.6\" y=\"187.4\" stroke=\"none\" fill=\"currentColor\" font-style=\"italic\" font-weight=\"600\">b</text><line x1=\"100\" y1=\"170\" x2=\"100\" y2=\"66\" marker-end=\"url(#agB)\" style=\"stroke:var(--accent);fill:none\" stroke-width=\"2\"/><text x=\"108\" y=\"86.8\" stroke=\"none\" style=\"fill:var(--accent)\" font-style=\"italic\" font-weight=\"600\">c = a × b</text><polyline points=\"100,158.8 97.9,162.7 97.9,173.9\" stroke-width=\"1\"/><polyline points=\"100,158.8 110.8,159.2 110.8,170.4\" stroke-width=\"1\"/><text x=\"150\" y=\"40\" stroke=\"none\" fill=\"currentColor\" font-size=\"11\">S = |a × b| = |a||b| sin φ</text></svg>",
