  "plane_normal": "<svg viewBox=\"0 0 320 210\" xmlns=\"http://www.w3.org/2000/svg\" class=\"fig\" font-size=\"12\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\"><defs><marker id=\"agA\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" fill=\"currentColor\" stroke=\"none\"/></marker><marker id=\"agB\" viewBox=\"0 0 10 10\" refX=\"9\" refY=\"5\" markerWidth=\"7\" markerHeight=\"7\" orient=\"auto-start-reverse\"><path d=\"M0,0 L10,5 L0,10 z\" style=\"fill:var(--accent)\" stroke=\"none\"/></marker></defs><polygon points=\"60,160 244,160 198.7,205.3 14.7,205.3\" fill=\"currentColor\" fill-opacity=\".08\" stroke=\"currentColor\" stroke-width=\"1\" stroke-opacity=\".5\"/><circle cx=\"91\" cy=\"177\" r=\"2.6\" fill=\"currentColor\" stroke=\"currentColor\"/><text x=\"69\" y=\"191\" stroke=\"none\" fill=\"currentColor\">M₀</text><circle cx=\"187.7\" cy=\"188.3\" r=\"2.6\" fill=\"currentColor\" stroke=\"currentColor\"/><text x=\"195.7\" y=\"194.3\" stroke=\"none\" fill=\"currentColor\">M</text><line x1=\"91\" y1=\"177\" x2=\"187.7\" y2=\"188.3\" marker-end=\"url(#agA)\"/><text x=\"138.5\" y=\"198.1\" stroke=\"none\" fill=\"currentColor\" font-style=\"italic\" font-weight=\"600\">M₀M</text><line x1=\"91\" y1=\"177\" x2=\"91\" y2=\"89\" marker-end=\"url(#agB)\" style=\"stroke:var(--accent);fill:none\" stroke-width=\"2\"/><text x=\"99\" y=\"97.4\" stroke=\"none\" style=\"fill:var(--accent)\" font-style=\"italic\" font-weight=\"600\">n = {A, B, C}</text><polyline points=\"91,165 101.3,166.2 101.3,178.2\" stroke-width=\"1\"/><text x=\"150\" y=\"26\" stroke=\"none\" fill=\"currentColor\" font-size=\"11\">n · M₀M = 0</text><text x=\"150\" y=\"40\" stroke=\"none\" fill=\"currentColor\" font-size=\"10.5\">A(x−x₀)+B(y−y₀)+C(z−z₀)=0</text></svg>",
